# Lambda handler attached to the Orders table stream (NEW_AND_OLD_IMAGES)
import time

def handler(event, context):
    for rec in event["Records"]:
        name = rec["eventName"]                    # INSERT | MODIFY | REMOVE
        keys = rec["dynamodb"]["Keys"]             # wire format: {"customer_id": {"S": "c1"}, ...}
        if name == "MODIFY":
            old = rec["dynamodb"]["OldImage"]["status"]["S"]
            new = rec["dynamodb"]["NewImage"]["status"]["S"]
            if old != new == "SHIPPED":
                print("notify", keys["customer_id"]["S"])   # must be idempotent
        elif name == "REMOVE" and rec.get("userIdentity", {}).get(
                "principalId") == "dynamodb.amazonaws.com":
            print("expired by TTL", keys)

# writing an item that expires in 7 days (TTL attribute "expires_at")
item = {"customer_id": "c1", "order_id": "cart",
        "expires_at": int(time.time()) + 7 * 24 * 3600}
